// Advance: Forward to a moment, at most the days' last; where the clock stands.
func (b *Bench) Advance(ctx context.Context, to any) (int64, error) {
	if err := b.mount(ctx); err != nil {
		return 0, err
	}
	vToMs, err := momentOf(to)
	if err != nil {
		return 0, err
	}
	a := map[string]any{"bench": b.URI}
	a["stop_at_end"] = json.RawMessage("true")
	a["to_ms"] = vToMs
	got, err := b.c.Call(ctx, "replay_seek", a)
	if err != nil {
		return 0, err
	}
	n, _ := obj(got)["cursor_ms"].(float64)
	return int64(n), nil
}

