// CloneOptions are Clone's optional arguments; a nil or empty field is absent.
type CloneOptions struct {
	State *bool
	Name string
}

// Clone: A workbench alike, in this one's state by default.
func (b *Bench) Clone(ctx context.Context, opts *CloneOptions) (*Bench, error) {
	if err := b.mount(ctx); err != nil {
		return nil, err
	}
	if opts == nil {
		opts = &CloneOptions{}
	}
	var vState any
	if !(opts.State == nil) {
		vState = *opts.State
	} else {
		vState = json.RawMessage("true")
	}
	var vName any
	if !(opts.Name == "") {
		vName = opts.Name
	}
	a := map[string]any{"bench": b.URI}
	a["state"] = vState
	a["name"] = vName
	got, err := b.c.Call(ctx, "bench_clone", a)
	if err != nil {
		return nil, err
	}
	made := obj(got)
	madeURI, _ := made["uri"].(string)
	madeName, _ := made["name"].(string)
	return &Bench{c: b.c, URI: madeURI, Name: madeName, raise: b.raise}, nil
}

// Keep: Keep where it stands, to watch on the chart: a clone in its state, under a name.
func (b *Bench) Keep(ctx context.Context, name string) (*Bench, error) {
	if err := b.mount(ctx); err != nil {
		return nil, err
	}
	a := map[string]any{"bench": b.URI}
	a["state"] = json.RawMessage("true")
	a["name"] = name
	got, err := b.c.Call(ctx, "bench_clone", a)
	if err != nil {
		return nil, err
	}
	made := obj(got)
	madeURI, _ := made["uri"].(string)
	madeName, _ := made["name"].(string)
	return &Bench{c: b.c, URI: madeURI, Name: madeName, raise: b.raise}, nil
}

